using System;
using System.IO;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using CastleStorySteam;
internal static class DesktopRelease {
 internal const int MaxBytes=32*1024*1024;
 internal static string CacheRoot {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CastleStorySteamBridge","ProgramUpdates");}}
 internal static byte[] SignedData(string version,byte[] app){return UpdateVerifier.SignedData("CastleStorySetup/"+version,app);}
 internal static bool Verify(string version,byte[] app,byte[] sig){Version parsed;if(!UpdateVerifier.TryParse(version,out parsed)||version.Split('.').Length!=3||app==null||app.Length<100||app.Length>MaxBytes||sig==null||sig.Length!=256)return false;try{using(RSACryptoServiceProvider rsa=new RSACryptoServiceProvider()){rsa.FromXmlString(UpdateKey.PublicXml);return rsa.VerifyData(SignedData(version,app),new SHA256Managed(),sig);}}catch{return false;}}
 internal static byte[] Build(string version,byte[] app,byte[] sig){if(!Verify(version,app,sig))throw new IOException("Підпис програми не підтверджено.");using(MemoryStream stream=new MemoryStream())using(BinaryWriter writer=new BinaryWriter(stream)){writer.Write(Encoding.ASCII.GetBytes("CSSW1"));byte[] v=Encoding.UTF8.GetBytes(version);writer.Write((byte)v.Length);writer.Write(v);writer.Write(app.Length);writer.Write(app);writer.Write(sig);byte[] blob=stream.ToArray();if(blob.Length>MaxBytes)throw new IOException("Пакет надто великий.");return blob;}}
 internal static void Parse(byte[] blob,out string version,out byte[] app,out byte[] sig){version=null;app=null;sig=null;if(blob==null||blob.Length<370||blob.Length>MaxBytes)throw new IOException("Некоректний розмір пакета.");using(MemoryStream stream=new MemoryStream(blob))using(BinaryReader reader=new BinaryReader(stream,new UTF8Encoding(false,true))){if(Encoding.ASCII.GetString(reader.ReadBytes(5))!="CSSW1")throw new IOException("Це не пакет Steam Bridge.");int length=reader.ReadByte();if(length<1||length>20)throw new IOException("Некоректна версія.");version=new UTF8Encoding(false,true).GetString(reader.ReadBytes(length));int count=reader.ReadInt32();if(count<100||count!=stream.Length-stream.Position-256)throw new IOException("Пакет неповний.");app=reader.ReadBytes(count);sig=reader.ReadBytes(256);if(!Verify(version,app,sig))throw new IOException("Підпис автора не збігається. Поточну програму збережено.");}}
 internal static string Store(string root,string version,byte[] app,byte[] sig){if(!Verify(version,app,sig))throw new IOException("Непідписана програма.");string hash;using(SHA256 sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(app)).Replace("-","").Substring(0,16);Directory.CreateDirectory(root);string folder=Path.Combine(root,version+"_"+hash),target=Path.Combine(folder,"CastleStory-Steam-App.exe");if(Valid(target,version))return target;if(Directory.Exists(folder))throw new IOException("Папка версії вже існує, її збережено.");string stage=Path.Combine(root,"stage_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);string staged=Path.Combine(stage,"CastleStory-Steam-App.exe");File.WriteAllBytes(staged,app);File.WriteAllBytes(staged+".sig",sig);File.WriteAllText(Path.Combine(stage,"version.txt"),version);if(AssemblyName.GetAssemblyName(staged).Version.ToString(3)!=version)throw new IOException("Версія файлу не збігається з підписаною версією.");Directory.Move(stage,folder);return target;}
 internal static bool Valid(string path,string version){try{return Verify(version,File.ReadAllBytes(path),File.ReadAllBytes(path+".sig"))&&AssemblyName.GetAssemblyName(path).Version.ToString(3)==version;}catch{return false;}}
 internal static string Latest(string root,string baseline){string result=null,best=baseline;if(!Directory.Exists(root))return null;foreach(string folder in Directory.GetDirectories(root)){try{string v=File.ReadAllText(Path.Combine(folder,"version.txt")).Trim(),p=Path.Combine(folder,"CastleStory-Steam-App.exe");if(UpdateVerifier.IsNewer(v,best)&&Valid(p,v)){best=v;result=p;}}catch{}}return result;}
 internal static string Quote(string value){if(value.IndexOf('"')>=0)throw new ArgumentException("Некоректний шлях.");return "\""+value.TrimEnd('\\')+"\"";}
}
